function classify(req) {
  const qualityWords = ["second", "fast", "secure", "encrypted", "reliable"];
  const lower = req.toLowerCase();
  return qualityWords.some(w => lower.includes(w)) ? "non-functional" : "functional";
}
console.log(classify("Pages must load in under 2 seconds"));

