function vagueness(req) {
  const vague = ["fast", "user-friendly", "some", "many", "usually", "efficient"];
  const lower = req.toLowerCase();
  return vague.some(w => lower.includes(w)) ? "VAGUE - rewrite it" : "CLEAR";
}
console.log(vagueness("The system should be fast"));

